// Time how long pendulums started at different tiny gaps stay together.
const g = 9.81, DT = 0.002, MAX_T = 40, LIMIT = 0.5;
const START = [2.0, 0.0, 2.4, 0.0];   // angle 1, speed 1, angle 2, speed 2

// The Python cell's equations (both arms 1 m, both masses 1 kg).
function deriv([t1, w1, t2, w2]) {
  const d = t1 - t2;
  const den = 3 - Math.cos(2 * d);
  const a1 = (-g * 3 * Math.sin(t1) - g * Math.sin(t1 - 2 * t2)
    - 2 * Math.sin(d) * (w2 * w2 + w1 * w1 * Math.cos(d))) / den;
  const a2 = (2 * Math.sin(d) * (w1 * w1 * 2 + g * 2 * Math.cos(t1) + w2 * w2 * Math.cos(d))) / den;
  return [w1, a1, w2, a2];
}
function rk4(s) {
  const add = (a, b, h) => a.map((v, i) => v + h * b[i]);
  const k1 = deriv(s), k2 = deriv(add(s, k1, DT / 2)), k3 = deriv(add(s, k2, DT / 2)), k4 = deriv(add(s, k3, DT));
  return s.map((v, i) => v + DT / 6 * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]));
}

function separation(eps) {
  let a = START.slice(), b = START.slice();
  b[0] += eps;
  for (let step = 1; step * DT <= MAX_T; step++) {
    a = rk4(a);
    b = rk4(b);
    const gap = Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0));
    if (gap > LIMIT) return step * DT;
  }
  return null;
}

const rows = [];
console.log('starting gap   splits after');
for (const exp of [-3, -5, -7, -9, -11, -13]) {
  const t = separation(10 ** exp);
  rows.push({ gap: 10 ** exp, seconds: t });
  console.log(('1e' + exp).padStart(12) + (t === null ? '   not within ' + MAX_T + ' s' : (t.toFixed(2) + ' s').padStart(15)));
}

const timed = rows.filter(r => r.seconds !== null);
if (timed.length > 1) {
  const span = timed.at(-1).seconds - timed[0].seconds;
  const factors = Math.log10(timed[0].gap / timed.at(-1).gap) / 2;
  console.log('\neach factor of 100 in precision buys ' + (span / factors).toFixed(2) + ' s on average');
}
const p = nb.get('pendulum');
if (p && p.lyapunov) {
  console.log('the Python cell\'s exponent, ' + p.lyapunov.toFixed(2) + ' per second, predicts ' +
    (Math.log(100) / p.lyapunov).toFixed(2) + ' s');
}

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'A hundred times better start, a fixed few seconds more',
  data: { values: timed },
  mark: { type: 'line', point: { size: 70 } },
  encoding: {
    x: { field: 'gap', type: 'quantitative', scale: { type: 'log', reverse: true }, axis: { format: '.0e' }, title: 'starting gap (radians), smaller to the right' },
    y: { field: 'seconds', type: 'quantitative', title: 'seconds until the pendulums split' },
  },
};
